h1 { font-size: 1.9rem; line-height: 1.2; margin: 0; text-wrap: balance; }
h2 { font-size: 1.35rem; line-height: 1.25; margin: 0; text-wrap: balance; min-width: 0; }
h3 { font-size: 1.05rem; line-height: 1.3; margin: 0; text-wrap: balance; }
p { margin: 0 0 .8rem; }
p, li { max-width: 65ch; }
a { color: var(--accent); }
a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
code { font-family: var(--mono); font-size: .86em; background: var(--code-bg); padding: .08em .3em; border-radius: 3px; overflow-wrap: anywhere; }
strong, b { font-weight: 700; }

header.top { display: flex; flex-direction: column; gap: .4rem; }
.stamp { order: -1; font-family: var(--mono); font-size: .78rem; color: var(--muted); letter-spacing: .02em; margin: 0; overflow-wrap: anywhere; }
.deck { color: var(--muted); margin: 0; }

section { border-top: 1px solid var(--rule); padding-top: 18px; min-width: 0; }
.head { display: flex; flex-wrap: wrap; align-items: baseline; gap: .4rem .6rem; margin-bottom: .6rem; }
button.select { font-family: var(--mono); font-size: .72rem; font-weight: 600; color: var(--accent); background: var(--surface); border: 1px solid var(--rule); border-radius: 4px; padding: .2em .6em; cursor: pointer; flex: none; -webkit-user-select: none; user-select: none; }
button.select:focus-visible, summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.speak { counter-reset: pt; display: flex; flex-direction: column; gap: .7rem; }
.speak p { margin: 0; }
.pt { counter-increment: pt; position: relative; padding-left: 1.9rem; }
.pt::before { content: counter(pt) "."; position: absolute; left: 0; top: 0; width: 1.5rem; text-align: right; font-family: var(--mono); font-size: .9em; color: var(--muted); }
article.pt::before { top: .1rem; }

.entry { display: flex; flex-direction: column; gap: .55rem; padding-block: .4rem .9rem; min-width: 0; }
.entry + .entry { border-top: 1px dashed var(--rule); padding-top: 1rem; }
.sizes { font-family: var(--mono); font-size: .8rem; color: var(--muted); font-variant-numeric: tabular-nums; margin: 0; }
.bars { display: flex; flex-direction: column; gap: 3px; }
.bar { height: 5px; border-radius: 3px; max-width: 100%; }
.bar.old { background: var(--old); }
.bar.new { background: var(--accent); }
blockquote.newtext { margin: 0; padding: 12px 16px; background: var(--surface); border: 1px solid var(--rule); border-left: 3px solid var(--accent); border-radius: 6px; min-width: 0; overflow-wrap: anywhere; }
details { min-width: 0; }
summary { cursor: pointer; font-size: .92rem; color: var(--accent); }
.oldtext { margin-top: .5rem; font-size: .88rem; color: var(--muted); overflow-wrap: anywhere; }
.oldtext code { background: none; padding: 0; }

.refs { font-size: .85rem; color: var(--muted); border-top: 1px dashed var(--rule); padding-top: .6rem; margin-top: 1rem; display: flex; flex-direction: column; gap: .3rem; min-width: 0; overflow-wrap: anywhere; }
.refs h3 { font-size: .85rem; font-weight: 700; color: var(--muted); margin: 0 0 .1rem; }
.refs p { margin: 0; max-width: none; }
.refs code { background: none; padding: 0; }
.figure { font-family: var(--mono); font-variant-numeric: tabular-nums; }
@media (prefers-reduced-motion: no-preference) { html { scroll-behavior: smooth; } }
